{
  "description": "A single quadrupedal creature is shown in right-facing profile standing on a small patch of sandy ground with sparse grass and tiny white flowers. The animal has a tan, short-furred mammalian body with four sturdy legs and a short, thick, bushy tail. Its head is feline in shape with a spotted tan face, amber eyes, and black tear-stripes. The entire dorsal region from the back of the neck to the rump and down the upper flanks is covered by a dense mantle of overlapping black feathers that contrasts sharply with the tan fur of the underside, chest, legs and tail. A narrow white stripe runs along the lower edge of the black mantle and a small yellow patch is visible at the front edge of the mantle near the shoulder.",
  "parts": [
    {
      "part": "head",
      "looks_like": "feline-shaped head at the front of the body, covered in short tan fur with small black spots on the forehead, crown and cheeks, a black nose, white fur on the muzzle, chin and throat, long white whiskers, amber eyes with black pupils, and a distinct black tear-line running from the inner corner of each eye down the side of the muzzle",
      "where": "anterior end of the body, held slightly above shoulder level and facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, upright ears with tan outer fur and darker gray-black fur on the back and inside, with slightly rounded tips",
      "where": "on top of the head, one more forward and one slightly behind, both visible in profile"
    },
    {
      "part": "mane",
      "looks_like": "a short ruff of slightly longer fur around the back and sides of the neck, tan at the base with black tips, giving a bristly appearance",
      "where": "encircling the neck just behind the ears and in front of the black feathered mantle"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular legs covered in short dense tan fur, with visible joints and slightly darker shading on the lower portions, standing in a natural quadrupedal stance",
      "where": "two forelegs beneath the chest and two hindlegs beneath the rump, all extending to the ground"
    },
    {
      "part": "feet",
      "looks_like": "four large rounded paws with tan fur, blunt toes and visible toe pads, each with short dark claws",
      "where": "at the distal ends of all four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a single short, thick, blunt-tipped tail covered in dense fluffy tan fur, hanging almost vertically with a slight outward curve",
      "where": "at the posterior end of the body, projecting from the rump above the hindlegs"
    },
    {
      "part": "feathers",
      "looks_like": "a dense covering of overlapping pointed black feathers with a slight sheen, layered like roof tiles, with a more scaly-textured appearance on the lower side area",
      "where": "covering the entire back and upper sides from just behind the neck and shoulders to the top of the rump, forming a saddle-like mantle"
    },
    {
      "part": "markings",
      "looks_like": "small black spots on the head and neck, solid black tear-stripes on the face, a solid black dorsal mantle, a narrow horizontal white stripe along the lower border of the mantle, and a small patch of yellow-orange fur at the anterior edge of the mantle on the shoulder",
      "where": "spots and tear-stripes on the face and neck, black mantle on the back and sides, white stripe along the ventral edge of the mantle, yellow patch at the shoulder junction between tan neck fur and black feathers"
    }
  ],
  "attached_objects": [],
  "animals": ["cheetah", "jackal", "bird"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
